<template>
  <section class="store-page">
    <div class="manage-page-heading"><div><span class="manage-eyebrow">{{ $ui(kind === 'plugin' ? '开发者控制台' : '创作者控制台') }}</span><h1>{{ selected?.name || $ui(creating ? '新建项目' : view === 'overview' ? '工作概览' : view === 'finance' ? '商店订单收入与提现' : categoryTitle) }}</h1></div><router-link v-if="creating || projectId" class="secondary-button" :to="basePath">{{ $ui('返回项目列表') }}</router-link><router-link v-else-if="view === 'projects' && allowed" class="primary-button" :to="basePath + '/new'">{{ $ui('新建项目') }}</router-link></div>
    <p v-if="checking" role="status">{{ $ui('正在检查会话…') }}</p>
    <section v-else-if="error && !session" class="work-panel"><p class="form-error" role="alert">{{ $ui(error) }}</p><button class="secondary-button" @click="initialize">{{ $ui('重新连接') }}</button></section>
    <section v-else-if="sidecar && session && !allowed" class="work-panel"><h2>{{ $ui('Sidecar 项目需要受信任开发者资格') }}</h2><DeveloperApplication kind="trusted_developer" embedded @granted="initialize" /></section>
    <section v-else-if="!allowed" class="work-panel"><p>{{ $ui('当前账户没有此类内容的发布资格') }}</p><router-link to="/account">{{ $ui('我的账户') }}</router-link></section>
    <template v-else>
      <p v-if="error" class="form-error" role="alert">{{ $ui(error) }}</p><p v-if="message" class="form-success" role="status">{{ $ui(message) }}</p>
      <PublisherContentSummary v-if="view === 'overview'" :show-console-link="false" :kind="kind" />
      <PublisherFinance v-else-if="view === 'finance'" />
      <section v-else-if="creating" class="work-panel project-create"><h2>{{ $ui('创建内容草稿') }}</h2><p class="store-muted">{{ $ui('创建草稿后，可在项目管理中完善介绍、提交版本和设置商品。') }}</p><form class="store-form" @submit.prevent="create"><label>{{ $ui('名称') }}<input v-model.trim="form.name" required maxlength="120" /></label><label>{{ $ui('简介') }}<input v-model.trim="form.summary" required maxlength="400" /></label><label>{{ $ui('详细介绍') }}<textarea v-model.trim="form.description" required maxlength="12000" rows="6" /></label><label>{{ $ui('价格（整数N代币，0表示免费）') }}<input v-model.number="form.tokenPrice" type="number" min="0" max="1000000000" step="1" required /></label><div class="actions"><button class="primary-button" :disabled="busy || testMode">{{ $ui('创建草稿') }}</button><router-link class="secondary-button" :to="basePath">{{ $ui('取消') }}</router-link></div></form></section>
      <template v-else-if="projectId">
        <div v-if="selected" class="project-editor">
          <nav class="project-settings-nav" :aria-label="$ui('项目设置')"><router-link v-for="entry in tabs" :key="entry.key" :to="{path:route.path,query:{tab:entry.key}}" :class="{active:tab === entry.key}" :aria-current="tab === entry.key ? 'page' : 'false'">{{ $ui(entry.label) }}</router-link></nav>
          <div class="project-editor-content">
            <div class="project-status"><span class="status-pill">{{ $ui(storeState(selected.state)) }}</span><code>{{ selected.id }}</code></div>
            <section v-if="tab === 'general' || tab === 'description'" class="work-panel"><h2>{{ $ui(tab === 'general' ? '基本信息' : '项目介绍') }}</h2><form class="store-form" @submit.prevent="save"><template v-if="tab === 'general'"><label>{{ $ui('名称') }}<input v-model.trim="form.name" required maxlength="120" /></label><label>{{ $ui('简介') }}<input v-model.trim="form.summary" required maxlength="400" /></label></template><label v-else>{{ $ui('详细介绍') }}<textarea v-model.trim="form.description" required maxlength="12000" rows="16" /></label><p class="store-muted">{{ $ui('保存信息不会发布项目或改变审核状态。') }}</p><button class="primary-button" :disabled="busy || testMode">{{ $ui('保存更改') }}</button><button v-if="conflict" type="button" class="secondary-button" @click="initialize">{{ $ui('重新加载项目') }}</button></form></section>
            <template v-else-if="tab === 'versions'">
              <section class="work-panel"><h2>{{ $ui('版本记录') }}</h2><p v-if="!releases.length" class="store-muted">{{ $ui('暂无版本。') }}</p><article v-for="release in releases" :key="release.id" class="store-content-row"><div><strong>{{ release.version }}</strong><small>{{ new Date(release.created_at).toLocaleString($locale) }}</small></div><span class="status-pill">{{ $ui(storeState(release.review_state)) }}</span></article></section>
              <section class="work-panel"><h2>{{ $ui('提交制品与发布版本') }}</h2><p v-if="kind === 'plugin' && !sidecar" class="store-muted">{{ $ui('插件包上传和下载暂未开放') }}</p><form v-else class="store-form" @submit.prevent="release"><label>{{ $ui('版本') }}<input v-model.trim="version" required maxlength="60" /></label><label>{{ $ui('制品文件（最多25MiB）') }}<input type="file" :accept="sidecar ? '.nsc' : undefined" required @change="selectFile" /></label><p class="store-muted">{{ $ui(sidecar ? 'Sidecar 发布需要与制品哈希一致的完整安全扫描；缺少扫描不会自动发布。' : '主题制品提交后等待人工审核。') }}</p><label v-if="sidecar">{{ $ui('VirusTotal 分析编号') }}<input v-model.trim="analysisId" maxlength="256" /></label><button class="primary-button" :disabled="busy || testMode || !file">{{ $ui('提交版本审核') }}</button></form></section>
            </template>
            <PublisherReviews v-else-if="tab === 'reviews'" :item-id="selected.id" />
            <template v-else><p class="store-muted">{{ $ui('真实付费与打款尚未开放；免费内容也需要账户购买取得拥有权。') }}</p><StoreDiscountEditor :item-id="selected.id" /><section v-if="kind === 'plugin'" class="work-panel"><h2>{{ $ui('新增插件内独立商品') }}</h2><form class="store-form" @submit.prevent="createProduct"><label>{{ $ui('商品标识') }}<input v-model.trim="sku" required pattern="[a-z][a-z0-9_-]{1,63}" maxlength="64" /></label><label>{{ $ui('商品名称') }}<input v-model.trim="skuName" required maxlength="120" /></label><label>{{ $ui('价格（整数N代币，0表示免费）') }}<input v-model.number="skuPrice" type="number" min="0" max="1000000000" step="1" required /></label><button class="secondary-button" :disabled="busy || testMode">{{ $ui('创建独立商品') }}</button></form><code v-if="createdProduct">{{ createdProduct }}</code></section></template>
          </div>
        </div>
      </template>
      <section v-else class="work-panel"><div class="section-heading"><h2>{{ $ui(categoryTitle) }}</h2><label class="project-search">{{ $ui('搜索项目') }}<input v-model="search" type="search" /></label></div><p class="store-muted">{{ $ui('显示最近100个项目。') }}</p><div v-if="filteredItems.length" class="project-list"><router-link v-for="item in filteredItems" :key="item.id" class="project-row" :to="basePath + '/' + encodeURIComponent(item.id)"><div><h3>{{ item.name }}</h3><p>{{ item.summary }}</p><small>{{ item.version || $ui('暂无版本。') }} · {{ $ui('{0} 人拥有', [item.owner_count]) }}</small></div><span class="status-pill">{{ $ui(storeState(item.state)) }}</span><span>{{ $ui('编辑项目') }} →</span></router-link></div><p v-else class="manage-empty">{{ $ui(search ? '没有匹配的项目。' : '还没有自己的内容。') }}</p></section>
    </template>
  </section>
</template>
<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, watch, reactive, ref } from 'vue';
import { useRoute, useRouter, onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router';
import { ApiError, platform, isTestSession, SESSION_EVENT, type Session } from '@/api/platform';
import { store, storeState, type StoreContent, type StoreKind } from '@/api/store';
import PublisherContentSummary from '@/components/PublisherContentSummary.vue';
import PublisherReviews from '@/components/PublisherReviews.vue';
import PublisherFinance from '@/components/PublisherFinance.vue';
import DeveloperApplication from '@/components/DeveloperApplication.vue';
import StoreDiscountEditor from '@/components/StoreDiscountEditor.vue';
import '@/styles/store.css';
import { ui } from '@/languages/localize';
const route = useRoute(), router = useRouter(), kind = computed<StoreKind>(() => route.meta.storeKind === 'theme' ? 'theme' : 'plugin');
const sidecar = computed(() => route.meta.projectType === 'sidecar'), projectType = computed(() => kind.value === 'plugin' ? sidecar.value ? 'sidecar' as const : 'plugin' as const : undefined);
const projectId = computed(() => String(route.params.projectId || '')), creating = computed(() => route.meta.projectCreate === true);
const basePath = computed(() => '/publisher/' + (kind.value === 'theme' ? 'themes' : sidecar.value ? 'sidecars' : 'plugins'));
const categoryTitle = computed(() => kind.value === 'theme' ? '主题项目' : sidecar.value ? 'Sidecar 项目' : '插件项目');
const tabs = [{key:'general',label:'基本信息'},{key:'description',label:'项目介绍'},{key:'versions',label:'版本记录'},{key:'monetization',label:'商品设置'},{key:'reviews',label:'评分与评价'}];
const tab = computed(() => tabs.some(t => t.key === route.query.tab) ? String(route.query.tab) : 'general');
const search = ref(''), conflict = ref(false), releases = ref<{id:string;version:string;review_state:string;created_at:string}[]>([]);
const filteredItems = computed(() => items.value.filter(item => (item.name+' '+item.summary).toLowerCase().includes(search.value.toLowerCase())));
const view = computed(() => !creating.value && !projectId.value && ['overview', 'finance'].includes(String(route.query.view)) ? String(route.query.view) : 'projects');
const session = ref<Session>(), checking = ref(true), busy = ref(false), error = ref(''), message = ref(''), items = ref<StoreContent[]>([]), selectedId = ref(''), summaryKey = ref(0);
const testMode = computed(() => isTestSession()), allowed = computed(() => sidecar.value ? session.value?.trustedDeveloper === 1 : kind.value === 'plugin' ? session.value?.developer === 1 || session.value?.trustedDeveloper === 1 : session.value?.creator === 1);
const form = reactive({ name: '', summary: '', description: '', tokenPrice: 0 }), selected = computed(() => items.value.find(item => item.id === selectedId.value));
const version = ref('1.0.0'), file = ref<File>(), analysisId = ref(''), sku = ref(''), skuName = ref(''), skuPrice = ref(0), createdProduct = ref('');
async function refresh() { if (projectId.value) { const result = await store.project(projectId.value); if (result.item.kind !== kind.value || (kind.value === 'plugin' && result.item.project_type !== projectType.value)) throw new Error('项目不存在或无权访问'); items.value = [result.item]; selectedId.value = result.item.id; releases.value = result.releases; } else { items.value = (await store.summary(kind.value, projectType.value)).items; } summaryKey.value++; }
async function perform(run: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; message.value = ''; try { await run(); await refresh(); } catch (e) { error.value = e instanceof Error ? e.message : '商店操作失败，请重试'; } finally { busy.value = false; } }
async function create() { if (busy.value) return; busy.value = true; error.value = ''; try { const result = await store.create({kind:kind.value,projectType:projectType.value,...form}); Object.assign(form,{name:'',summary:'',description:''}); await router.push(basePath.value + '/' + encodeURIComponent(result.id)); } catch(e) { error.value = e instanceof Error ? e.message : '商店操作失败，请重试'; } finally { busy.value = false; } }
async function save() { if (busy.value || !selected.value) return; busy.value = true; error.value = ''; conflict.value = false; try { const result = await store.update(selected.value, {name:form.name,summary:form.summary,description:form.description}); items.value = [result.item]; message.value = '项目已保存。'; } catch(e) { conflict.value = e instanceof ApiError && e.status === 412; error.value = e instanceof Error ? e.message : '商店操作失败，请重试'; } finally { busy.value = false; } }
function selectFile(event: Event) { file.value = (event.target as HTMLInputElement).files?.[0]; }
function release() { if ((!sidecar.value && kind.value !== 'theme') || !selected.value || !file.value) return; const item = selected.value, uploadFile = file.value; void perform(async () => { const artifact = await store.upload(kind.value, uploadFile, projectType.value); await store.release(item, artifact.id, version.value, analysisId.value || undefined); message.value = '版本已提交，发布状态以审核结果为准。'; }); }
function createProduct() { if (!selected.value) return; const id = selected.value.id; void perform(async () => { const result = await store.createProduct(id, sku.value, skuName.value, skuPrice.value); createdProduct.value = result.id; sku.value = ''; skuName.value = ''; message.value = '独立商品已创建，付费购买仍保持关闭。'; }); }
const dirty = computed(() => creating.value ? Boolean(form.name || form.summary || form.description) : Boolean(selected.value && ['name','summary','description'].some(key => form[key as 'name'|'summary'|'description'] !== selected.value?.[key as 'name'|'summary'|'description'])));
function confirmLeave() { return !dirty.value || window.confirm(ui('尚有未保存的修改，确定离开吗？')); }
onBeforeRouteLeave(confirmLeave);
onBeforeRouteUpdate((to, from) => to.path === from.path || confirmLeave());
const beforeUnload = (event: BeforeUnloadEvent) => { if (dirty.value) { event.preventDefault(); event.returnValue = ''; } };
let generation = 0;
async function initialize() { const step = ++generation; checking.value = true; items.value = []; selectedId.value = ''; file.value = undefined; error.value = ''; message.value = ''; analysisId.value = ''; Object.assign(form, { name: '', summary: '', description: '', tokenPrice: 0 }); try { const current = await platform.refreshSession(); if (step !== generation) return; session.value = current; if (!current) { await router.replace({ path: '/login', query: { return: route.fullPath } }); return; } if (allowed.value && !creating.value) { await refresh(); if (step === generation && selected.value) Object.assign(form, {name:selected.value.name,summary:selected.value.summary,description:selected.value.description}); } } catch (e) { if (step === generation) error.value = e instanceof Error ? e.message : '内容概览读取失败'; } finally { if (step === generation) checking.value = false; } }
watch(() => [kind.value, projectType.value], initialize);
onMounted(() => { window.addEventListener('beforeunload', beforeUnload); window.addEventListener(SESSION_EVENT, initialize); void initialize(); });
onBeforeUnmount(() => { window.removeEventListener('beforeunload', beforeUnload); generation++; window.removeEventListener(SESSION_EVENT, initialize); });
</script>
<style scoped>
.project-editor{display:grid;grid-template-columns:180px minmax(0,1fr);gap:24px}.project-settings-nav{display:flex;flex-direction:column;gap:4px;align-self:start}.project-settings-nav a{padding:12px;border-radius:8px;font-size:14px}.project-settings-nav .active{background:var(--market-accent-soft);color:var(--nc-accent);font-weight:600}.project-editor-content{min-width:0}.project-editor-content .work-panel:first-of-type{margin-top:16px}.project-status{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.project-status code{font-size:11px;overflow-wrap:anywhere;color:var(--market-muted)}.project-create{max-width:850px}.project-list{display:grid}.project-row{display:flex;align-items:center;gap:20px;padding:22px 0;border-bottom:1px solid var(--market-border)}.project-row>div{flex:1;min-width:0}.project-row p{font-size:13px;color:var(--market-muted);margin:8px 0;overflow-wrap:anywhere}.project-row:hover h3{color:var(--nc-accent)}.project-row h3{overflow-wrap:anywhere}.project-search{display:flex;gap:10px;align-items:center;font-size:13px}.project-search input{min-width:0;max-width:180px;padding:8px;border:1px solid var(--market-border);border-radius:8px;background:var(--market-surface);color:var(--market-text)}@media(max-width:800px){.project-editor{grid-template-columns:1fr}.project-settings-nav{flex-direction:row;overflow-x:auto}.project-settings-nav a{white-space:nowrap}.project-row{flex-wrap:wrap}.project-row>div{flex-basis:100%}.project-search{width:100%}}
</style>
